/* --- Componentes extra --- */
.badge{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border-radius:99px;font-size:12px;font-weight:600;background:var(--g);border:1px solid var(--gb)}
.badge.ok{color:#34d399;border-color:rgba(52,211,153,.4);background:rgba(52,211,153,.1)}
.badge.warn{color:#fbbf24;border-color:rgba(251,191,36,.4);background:rgba(251,191,36,.1)}
.badge.err{color:#f87171;border-color:rgba(248,113,113,.4);background:rgba(248,113,113,.1)}
.alert{padding:12px 16px;border-radius:var(--r-m);border:1px solid var(--gb);background:var(--g);display:flex;gap:10px;align-items:flex-start}
.alert.ok{border-color:rgba(52,211,153,.45);background:rgba(52,211,153,.08)}
.alert.warn{border-color:rgba(251,191,36,.45);background:rgba(251,191,36,.08)}
.alert.err{border-color:rgba(248,113,113,.45);background:rgba(248,113,113,.08)}
.skel{position:relative;overflow:hidden;background:rgba(255,255,255,.06);border-radius:var(--r-m);min-height:16px}
.skel:after{content:"";position:absolute;inset:0;transform:translateX(-100%);background:linear-gradient(90deg,transparent,rgba(255,255,255,.1),transparent);animation:sk 1.4s infinite}
@keyframes sk{to{transform:translateX(100%)}}
.divider{height:1px;background:var(--gb);border:0;margin:16px 0}
.kbd{font:600 12px ui-monospace,Menlo,monospace;padding:2px 7px;border-radius:7px;background:rgba(255,255,255,.1);border:1px solid var(--gb)}
.progress{height:6px;border-radius:99px;background:rgba(255,255,255,.1);overflow:hidden}
.progress>i{display:block;height:100%;background:var(--grad);border-radius:inherit}
.sheet{position:fixed;left:0;right:0;bottom:0;z-index:45;padding:20px 16px calc(20px + env(safe-area-inset-bottom));background:rgba(14,10,40,.96);border-top:1px solid var(--gb2);border-radius:var(--r-xl) var(--r-xl) 0 0;box-shadow:0 -20px 60px rgba(0,0,0,.6);backdrop-filter:blur(24px)}
.sheet:before{content:"";display:block;width:40px;height:4px;border-radius:4px;background:rgba(255,255,255,.25);margin:0 auto 14px}
.scrim{position:fixed;inset:0;z-index:44;background:rgba(3,2,12,.6);backdrop-filter:blur(3px)}
@keyframes fadeup{from{opacity:0;transform:translateY(10px)}}
.anim-in{animation:fadeup .35s var(--ease)}
